val VietnameseStrings = AppStrings()
val EnglishStrings = AppStrings()

val LocalStrings = compositionLocalOf { VietnameseStrings }

@Composable
fun ProvideStrings(language: String = "vi", content: @Composable () -> Unit) {
    val context = LocalContext.current
    val localizedStrings = remember(language, context) {
        val locale = java.util.Locale.forLanguageTag(if (language == "en") "en" else "vi")
        val configuration = android.content.res.Configuration(context.resources.configuration).apply {
            setLocale(locale)
        }
        val localizedContext = context.createConfigurationContext(configuration)
        AppStrings(localizedContext)
    }
    androidx.compose.runtime.CompositionLocalProvider(LocalStrings provides localizedStrings, content = content)
}
